    <nav className="hidden items-center gap-8 text-sm font-medium text-[#53625b] xl:flex"><Link href="/products">Offerings</Link><Link href="/solutions">Solutions</Link><Link href="/insights">Insights</Link><Link href="/media">Media</Link><Link href="/about">About</Link><Link href="/#how">How it works</Link><Link href="/learning">Collective learning</Link><Link href="/connect">Contact</Link></nav>
