function PublicRouter({ path }: { path: string }) {
  if (path === "/products") return <Products />;
  if (path === "/connect") return <PublicForm kind="demo" />;
  if (path === "/hackathon/register") return <PublicForm kind="hackathon" />;
  if (path === "/login") return <Login />;
  if (path === "/signin" || path === "/register") return <SignIn initialMode={path === "/register" ? "signup" : "signin"} />;
  if (path === "/accept-invite") return <AcceptInvite />;
  if (path === "/solutions") return <Solutions />;
  if (path === "/insights") return <Insights />;
  if (path === "/media" || path === "/live") return <Media live={path === "/live"} />;
  if (path === "/lab") return <PublicLab />;
  if (path === "/about") return <About />;
  return <><Landing /><PublicUpdates /></>;
}

