  async function rate(id: string, rating: string) { try { await api("/api/portal", { method: "POST", body: JSON.stringify({ action: "add_feedback", kind: "knowledge", refId: id, rating, comment: "" }) }); setNotice("Feedback recorded."); load(); } catch (x) { setError((x as Error).message); } }
